import re, sqlite3

_SURFACES = {"support_tickets":{"table":"support_tickets","primary_key":"id","labels":["ticket_number","subject","customer_name"],"readable":["id","ticket_number","subject","customer_name","priority","assignee_employee_id","opened_at","lead_management_sop_id","status"],"resolvable":["ticket_number","subject","customer_name","priority","assignee_employee_id","opened_at","lead_management_sop_id"],"mutable":["ticket_number","subject","customer_name","priority","opened_at","status"],"lifecycles":{"status":["open","in_progress","waiting_customer","resolved","closed"]}}}

def _qi(name):
